TRAD = "buda"
C = [
("de", "Dhammapada 1-2", "O que precede todos os estados, segundo os versos de abertura do Dhammapada?", "A mente: agindo com mente impura, o sofrimento segue como a roda segue o boi; com mente pura, a felicidade segue como a sombra.", "Antes de agir, cheque o estado da mente."),
("ra", "Dhammapada 5", "Como o ódio cessa, segundo a 'lei eterna' do Dhammapada?", "O ódio nunca cessa pelo ódio; cessa pelo não-ódio (amor).", "Não alimente o ciclo — corte a próxima volta."),
("ra", "Dhammapada 6", "O que faz cessar as brigas, segundo o verso 6?", "Lembrar que aqui todos morreremos.", "Perspectiva de finitude diminui a disputa."),
("tr", "Dhammapada 21", "Qual é o caminho para o imortal, segundo o verso 21?", "A atenção vigilante (appamāda); a negligência é o caminho da morte.", "Atenção é treino, não traço fixo."),
("tr", "Dhammapada 25", "Que ilha o sábio constrói, segundo o verso 25?", "Pelo esforço, vigilância, disciplina e autocontrole, faz de si uma ilha que nenhuma enchente submerge.", "Rotina é a sua ilha na enchente."),
("tr", "Dhammapada 33", "Como o sábio trata a mente agitada e instável?", "Endireita-a como o arqueiro endireita a flecha.", "Mente dispersa não é falha: é matéria-prima a endireitar."),
("tr", "Dhammapada 35", "Por que domar a mente, segundo o verso 35?", "Ela é veloz, difícil de conter e pousa onde quer; a mente domada traz felicidade.", "Um foco por vez, com timer."),
("de", "Dhammapada 42-43", "Quem pode fazer mais mal ou mais bem do que inimigos e parentes?", "A própria mente: mal dirigida faz pior que um inimigo; bem dirigida, melhor que pai e mãe.", "Seu diálogo interno é seu maior aliado ou rival."),
("hu", "Dhammapada 50", "Para onde olhar, segundo o verso 50?", "Não para as faltas dos outros, mas para o que eu mesmo fiz e deixei de fazer.", "Em conflito, comece pela sua parte."),
("ju", "Dhammapada 51", "Com o que se parecem belas palavras de quem não pratica?", "Com uma flor bonita, mas sem perfume.", "Palavra com prática tem perfume."),
("am", "Dhammapada 61", "O que fazer se não houver companhia melhor ou igual?", "Seguir firme sozinho: não há companheirismo com o tolo.", "Melhor só do que mal acompanhado — sem se isolar dos bons."),
("hu", "Dhammapada 76", "Como ver quem aponta nossas faltas?", "Como quem revela um tesouro escondido.", "Agradeça a crítica justa."),
("af", "Dhammapada 81", "Como o sábio reage a louvor e censura?", "Como a rocha sólida que o vento não abala.", "Nem o elogio nem a ofensa governam você."),
("pa", "Dhammapada 100", "O que vale mais que mil palavras vazias?", "Uma única palavra útil que traz paz a quem a ouve.", "Uma frase de paz basta."),
("ra", "Dhammapada 103", "Qual a maior vitória, segundo o verso 103?", "Vencer a si mesmo vale mais que vencer mil vezes mil homens.", "Vencer o impulso é a batalha real."),
("tr", "Dhammapada 121", "Por que não subestimar um pequeno mal?", "Gota a gota enche-se o pote; o tolo se enche de mal aos poucos.", "Hábito ruim pequeno também enche o pote."),
("tr", "Dhammapada 122", "Como o sábio se enche de bem?", "Gota a gota, como o pote se enche de água.", "Uma boa ação pequena por dia."),
("ju", "Dhammapada 129-130", "Que raciocínio sustenta a não-violência no Dhammapada?", "Todos temem a violência e amam a vida; pondo-se no lugar do outro, não se fere nem se manda ferir.", "Empatia como freio."),
("ju", "Dhammapada 165", "Quem purifica a quem, segundo o verso 165?", "Por si mesmo se faz o mal, por si mesmo se purifica; ninguém purifica o outro.", "Responsabilidade pessoal, sem terceirizar."),
("ju", "Dhammapada 183", "Como os Budas resumem o ensinamento?", "Não fazer mal algum, cultivar o bem e purificar a mente.", "Três verbos para o dia: evitar, cultivar, purificar."),
("ra", "Dhammapada 197", "Como viver entre os que odeiam, segundo o verso 197?", "Felizes, sem ódio, entre os que odeiam.", "Não deixe o ódio alheio morar em você."),
("gr", "Dhammapada 204", "Quais são o maior ganho e a maior riqueza?", "A saúde é o maior ganho; o contentamento, a maior riqueza; a confiança, o melhor parente.", "Proteja saúde e contentamento como patrimônio."),
("ra", "Dhammapada 223", "Como vencer raiva, mal, avareza e mentira?", "A raiva com a não-raiva, o mal com o bem, o avarento com a generosidade, o mentiroso com a verdade.", "Escolha o oposto da agressão recebida."),
("pa", "Dhammapada 232", "O que guardar na fala, segundo o verso 232?", "Guardar-se da agitação da fala: abandonar a fala ruim e cultivar a boa.", "Releia a mensagem antes de enviar."),
("hu", "Dhammapada 252", "O que é fácil e o que é difícil de ver?", "Fácil ver as faltas alheias; difícil ver as próprias.", "Procure seu ponto cego com alguém de confiança."),
("tr", "Dhammapada 276", "Qual o papel dos Budas e o nosso?", "Eles apenas apontam o caminho; o esforço é nosso.", "Mapa não anda por você."),
("es", "Dhammapada 277", "O que se vê com sabedoria sobre as coisas condicionadas?", "Que todas são impermanentes — e assim se afasta do sofrimento.", "Isto também passa."),
("de", "Dhammapada 282", "De onde nasce a sabedoria, segundo o verso 282?", "Da meditação (prática); sem ela, a sabedoria se perde.", "5 minutos de silêncio por dia."),
("af", "Dhammapada 160", "Qual é o refúgio do eu, segundo o verso 160?", "O próprio eu, bem disciplinado — quem mais seria?", "Construa recursos internos."),
("af", "Dhammapada 227", "Há alguém que nunca foi criticado?", "Não: censuram quem fala muito, quem fala pouco e quem se cala — sempre foi assim.", "Crítica é inevitável; não a tome como medida de valor."),
("me", "Dhammapada 212", "De onde nascem tristeza e medo, segundo o verso 212?", "Do que é querido e do apego.", "Ame sem prender."),
("tr", "Dhammapada 80", "O que o sábio molda, segundo o verso 80?", "Irrigadores conduzem água, flecheiros endireitam flechas, carpinteiros moldam madeira; o sábio molda a si mesmo.", "Você é a sua obra-prima."),
("de", "Kalama Sutta (AN 3.65)", "Como avaliar um ensinamento, segundo o Kalama Sutta?", "Não aceitar por tradição, boato, escritura, lógica ou autoridade; quando souber por si que algo é nocivo, abandone; se benéfico, pratique.", "Vale também para promessas de dinheiro: teste e verifique."),
("af", "Sallatha Sutta (SN 36.6)", "O que é a 'segunda flecha'?", "A dor é a primeira flecha; a angústia mental que acrescentamos é a segunda.", "Sinta a primeira; recuse a segunda."),
("fa", "Karaniya Metta Sutta (Sn 1.8)", "Que imagem o Metta Sutta usa para o amor ilimitado?", "Como a mãe protege o filho único com a própria vida, cultivar amor sem limites por todos.", "Envie mentalmente bons votos a alguém difícil."),
("pa", "Abhaya Sutta (MN 58)", "Que fala o Buda usa, segundo o Abhaya Sutta?", "Só a verdadeira e benéfica, no momento oportuno — mesmo se desagradável.", "Verdadeira? Útil? Hora certa?"),
("pa", "Vaca Sutta (AN 5.198)", "Quais as cinco marcas da fala bem dita?", "No tempo certo, verdadeira, gentil, benéfica e dita com boa vontade.", "Passe a mensagem por esses 5 filtros."),
("fa", "Sigalovada Sutta (DN 31)", "Quais deveres do filho com os pais no Sigalovada?", "Sustentá-los, cumprir seus deveres, manter a família, ser digno da herança e honrá-los após a morte.", "Cuidado com os pais é parte do caminho."),
("di", "Sigalovada Sutta (DN 31)", "Como dividir a renda, segundo o conselho a Sigala?", "Em quatro partes: uma para viver, duas para o trabalho/negócio, uma guardada para necessidades.", "Separe sua reserva antes de gastar."),
("di", "Sigalovada Sutta (DN 31)", "Quais canais dissipam a riqueza, segundo DN 31?", "Intoxicantes, rua em horas impróprias, festas, jogo, más companhias e preguiça.", "Identifique seu 'canal de vazamento'."),
("am", "Sigalovada Sutta (DN 31)", "Quais os quatro falsos amigos de DN 31?", "O que só toma, o que só fala, o bajulador e o companheiro de dissipação.", "Observe quem só aparece para pedir."),
("am", "Upaddha Sutta (SN 45.2)", "Quanto vale a amizade nobre, segundo o Buda a Ananda?", "Não é metade da vida santa — é a vida santa inteira.", "Invista em uma amizade nobre."),
("de", "Dhammacakkappavattana Sutta (SN 56.11)", "Qual é o 'caminho do meio' do primeiro sermão?", "Evitar os dois extremos: a indulgência nos prazeres e a autotortura.", "Nem excesso, nem punição: equilíbrio."),
("es", "Kisa Gotami (comentário ao Dhammapada 114)", "O que Kisa Gotami aprende ao buscar uma semente de mostarda?", "Que não há casa onde ninguém tenha morrido: a perda é universal.", "Luto compartilhado pesa menos."),
("de", "Parábola da jangada (MN 22)", "Para que serve a jangada, segundo o Buda?", "Para atravessar o rio — não para carregar nas costas depois.", "Use as ferramentas; não se apegue a elas."),
("de", "Parábola da flecha envenenada (MN 63)", "O que o homem ferido não deve fazer antes de tirar a flecha?", "Perguntar quem atirou, de que casta era, de que madeira é o arco.", "Primeiro o urgente, depois as perguntas."),
("tr", "Sona Sutta (AN 6.55)", "O que a analogia do alaúde ensina a Sona?", "Corda tensa demais arrebenta; frouxa demais não soa: o esforço deve ser equilibrado.", "Estudo afinado: nem frouxo, nem exaustivo."),
("me", "Anapanasati Sutta (MN 118)", "Qual o ponto de partida da atenção à respiração?", "Inspirando longo, saber que inspira longo; expirando curto, saber que expira curto.", "3 respirações conscientes antes de responder."),
("me", "Vitakkasanthana Sutta (MN 20)", "Quais os cinco métodos contra pensamentos indesejados?", "Substituir pelo oposto; ver o perigo; não dar atenção; acalmar o pensamento; por fim, firme determinação.", "Use na ruminação noturna, em ordem."),
("ra", "Visuddhimagga IX.23 (Buddhaghosa)", "Com o que se parece quem se enraivece para ferir o outro?", "Com quem pega brasa viva ou excremento para atirar: primeiro queima ou suja a si mesmo.", "Raiva fere primeiro quem a segura."),
("es", "Mahaparinibbana Sutta (DN 16)", "Quais as últimas palavras atribuídas ao Buda?", "Todas as coisas condicionadas são impermanentes; esforçai-vos com diligência.", "Impermanência motiva, não paralisa."),
("ra", "Kakacupama Sutta (MN 21)", "Qual o símile extremo da serra?", "Mesmo se bandidos te serrassem membro a membro, quem cedesse ao ódio não seguiria o ensinamento.", "O padrão da não-raiva é alto — pratique no pequeno."),
("tr", "Dhammapada 116", "O que fazer com o impulso de fazer o bem, segundo o verso 116?", "Apressar-se em fazê-lo; quem é lento no bem deixa a mente se comprazer no mal.", "Boa ideia? Execute um pedaço em 2 minutos."),
]
